def resolve_environment_variables(config: configparser.ConfigParser) -> configparser.ConfigParser:
    for section in config.sections():
        for key, value in config.items(section):
            if value.startswith("$") and value[1:] in os.environ:
                config.set(section, key, os.environ[value[1:]])

    return config

def apply_overrides(config: configparser.ConfigParser, overrides: dict) -> configparser.ConfigParser:
    for section, options in overrides.items():
        if not config.has_section(section):
            config.add_section(section)
        for option, value in options.items():
            config.set(section, option, value)

    return config

